 15	/// On success, writes the entry through to the `entries` Hive box (`Box
 16	/// <Map>`, keyed by id, raw `EntryDto.toJson()` — Design Notes) *before*
 17	/// returning `right(...)`, same "persist then return" ordering
 18	/// `AuthRepositoryImpl._authenticate` already uses for its own
 19	/// post-success side effect.
 20	class EntriesRepositoryImpl implements EntriesRepository {
 21	  EntriesRepositoryImpl({
 22	    required EntriesRemoteDataSource remoteDataSource,
 23	    required Box<Map> entriesBox,
 24	  }) : _remoteDataSource = remoteDataSource,
 25	       _entriesBox = entriesBox;
 26	
 27	  final EntriesRemoteDataSource _remoteDataSource;
 28	  final Box<Map> _entriesBox;
 29	
 30	  @override
 31	  Future<Either<Failure, Entry>> create({
 32	    required String content,
 33	    required EntrySource source,
 34	    int? mediaDurationSeconds,
 35	  }) async {
 36	    final result = await _remoteDataSource.create(
 37	      content: content,
 38	      source: source,
 39	      mediaDurationSeconds: mediaDurationSeconds,
 40	    );
 41	    return result.match((failure) async => left(failure), (dto) async {
 42	      // A thrown Hive/disk exception must never escape unmapped (RNF09) —
 43	      // same rationale/fallback `AuthRepositoryImpl` already uses for its
 44	      // own local-persistence step.
 45	      try {
 46	        await _entriesBox.put(dto.id, dto.toJson());
 47	      } catch (error) {
 48	        return left(Failure.malformedResponse(message: error.toString()));
 49	      }
 50	      return right(_toEntry(dto));
 51	    });
 52	  }
 53	
 54	  @override
 55	  Future<Either<Failure, EntriesPage>> list({
 56	    String? cursor,
 57	    int limit = 20,
 58	  }) async {
 59	    final result = await _remoteDataSource.list(cursor: cursor, limit: limit);
 60	    return result.match(
 61	      (failure) async {
 62	        // Boundaries/Design Notes: the Hive-cache fallback is scoped to
 63	        // `cursor == null` (the first/fresh page) only — a paginated
 64	        // continuation (`cursor != null`) that fails with
 65	        // `networkOffline`/`networkTimeout` propagates as `Left` like any
 66	        // other pagination failure instead, so `MeusRegistrosCubit`'s own
 67	        // `loadMoreFailed`/retry path handles it uniformly rather than a
 68	        // full unrelated cache dump silently replacing the in-progress
 69	        // paginated list (and breaking its newest-first ordering).
 70	        if (cursor == null &&
 71	            (failure is NetworkOffline || failure is NetworkTimeout)) {
 72	          return _offlineFallback();
 73	        }
 74	        return left(failure);
 75	      },
 76	      (page) async {
 77	        try {
 78	          await _entriesBox.putAll({
 79	            for (final dto in page.items) dto.id: dto.toJson(),
 80	          });
 81	        } catch (error) {
 82	          // Same RNF09 rationale as `create()`'s own Hive-write guard — a
 83	          // thrown Hive/disk exception must never escape unmapped.
 84	          return left(Failure.malformedResponse(message: error.toString()));
 85	        }
 86	        return right(
 87	          EntriesPage(
 88	            items: page.items.map(_toEntry).toList(),
 89	            nextCursor: page.nextCursor,
 90	          ),
 91	        );
 92	      },
 93	    );
 94	  }
 95	
 96	  @override
 97	  Future<Either<Failure, Entry>> getById(String id) async {
 98	    final result = await _remoteDataSource.get(id);
 99	    return result.match(
100	      (failure) async {
101	        // Boundaries: scoped to networkOffline/networkTimeout specifically
102	        // — every other Failure (notFound included) propagates as Left,
103	        // unmapped, same convention `list()`'s own cursor-scoped fallback
104	        // above uses.
105	        if (failure is NetworkOffline || failure is NetworkTimeout) {
106	          return _cachedEntryOrOriginalFailure(id, failure);
107	        }
108	        return left(failure);
109	      },
110	      (dto) async {
111	        // Same RNF09 rationale as `create()`/`list()`'s own Hive-write
112	        // guards — a thrown Hive/disk exception must never escape
113	        // unmapped.
114	        try {
115	          await _entriesBox.put(dto.id, dto.toJson());
116	        } catch (error) {
117	          return left(Failure.malformedResponse(message: error.toString()));
118	        }
119	        return right(_toEntry(dto));
120	      },
121	    );
122	  }
123	
124	  @override
125	  Future<Either<Failure, List<Entry>>> search(String query) async {
126	    final result = await _remoteDataSource.search(query);
127	    return result.match(
128	      (failure) async {
129	        // Boundaries/AD-9: no cache fallback for search, unlike
130	        // list()/getById() — every Failure (including
131	        // networkOffline/networkTimeout) propagates as Left, unmapped.
132	        return left(failure);
133	      },
134	      (dtos) async {
135	        // Review finding: de-duplicated by id first (first-occurrence-wins,
136	        // same semantics as `MeusRegistrosCubit._dedupedById`'s own
137	        // trust-but-verify convention for server data) — so the `putAll`
138	        // below and the returned list stay consistent, and
139	        // `_SearchResults`' `ListView.builder` (keyed by `ValueKey(entry.
140	        // id)`) never sees a duplicate key even if the backend ever
141	        // violated its own no-duplicate-ids invariant.
142	        final dedupedDtos = _dedupedById(dtos);
143	        // Same RNF09 rationale as create()/list()/getById()'s own
144	        // Hive-write guards — a thrown Hive/disk exception must never
145	        // escape unmapped.
146	        try {
147	          await _entriesBox.putAll({
148	            for (final dto in dedupedDtos) dto.id: dto.toJson(),
149	          });
150	        } catch (error) {
151	          return left(Failure.malformedResponse(message: error.toString()));
152	        }
153	        return right(dedupedDtos.map(_toEntry).toList());
154	      },
155	    );
156	  }
157	
158	  /// [getById]'s own offline/timeout fallback (Boundaries): a cache hit
159	  /// returns `Right` from the cached `EntryDto`; a cache miss propagates
160	  /// [originalFailure] unchanged — "no synthesized not-found" — rather than
161	  /// inventing a [Failure.notFound] this repository never actually
162	  /// received from the backend. A corrupt cached entry (should never
163	  /// happen — every entry here was written by [create]/[list]/[getById]
164	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
165	  /// (RNF09), same guard `_offlineFallback()`'s own malformed-cache check
166	  /// uses.
167	  Either<Failure, Entry> _cachedEntryOrOriginalFailure(
168	    String id,
169	    Failure originalFailure,
170	  ) {
171	    try {
172	      final cached = _entriesBox.get(id);
173	      if (cached == null) {
174	        return left(originalFailure);
175	      }
176	      return right(_toEntry(EntryDto.fromJson(Map<String, dynamic>.from(cached))));
177	    } catch (error) {
178	      return left(Failure.malformedResponse(message: error.toString()));
179	    }
180	  }
181	
182	  /// The offline/timeout fallback (Boundaries): a full `entries` Hive box
183	  /// dump, sorted `occurredAt` desc, always `nextCursor: null` — a cached
184	  /// dump has no further page to request. A corrupt cached entry (should
185	  /// never happen — every entry here was written by [create]/[list]
186	  /// themselves) maps to `Left(malformedResponse)` rather than throwing
187	  /// (RNF09), same guard `create()`'s own Hive write already has.
188	  Either<Failure, EntriesPage> _offlineFallback() {
189	    try {
190	      final entries =
191	          _entriesBox.values
192	              .map(
193	                (json) => _toEntry(
194	                  EntryDto.fromJson(Map<String, dynamic>.from(json)),
195	                ),
196	              )
197	              .toList()
198	            ..sort(
199	              (a, b) =>
200	                  DateTime.parse(b.occurredAt)
201	                      .compareTo(DateTime.parse(a.occurredAt)),
202	            );
203	      return right(EntriesPage(items: entries, nextCursor: null));
204	    } catch (error) {
205	      return left(Failure.malformedResponse(message: error.toString()));
206	    }
207	  }
208	
209	  Entry _toEntry(EntryDto dto) => Entry(
210	    id: dto.id,
211	    content: dto.content,
212	    source: dto.source,
213	    chatMessageId: dto.chatMessageId,
214	    occurredAt: dto.occurredAt,
215	    serverRevision: dto.serverRevision,
216	    createdAt: dto.createdAt,
217	    updatedAt: dto.updatedAt,
218	    mediaDurationSeconds: dto.mediaDurationSeconds,
219	  );
220	}
221	
222	/// [search]'s own trust-but-verify guard (Review finding) — first-
223	/// occurrence-wins, same semantics as `MeusRegistrosCubit._dedupedById`'s
224	/// own defensive de-duplication of server data, applied here to the raw
225	/// [EntryDto] list before it's ever persisted or mapped, so both the Hive
226	/// box write and the returned `List<Entry>` stay duplicate-free and
227	/// consistent with each other.
228	List<EntryDto> _dedupedById(List<EntryDto> dtos) {
229	  final seen = <String>{};
230	  return [
231	    for (final dto in dtos)
232	      if (seen.add(dto.id)) dto,
233	  ];
234	}

