 85	  @override
 86	  void initState() {
 87	    super.initState();
 88	    widget.cubit.loadFirstPage();
 89	    _skeletonTimer = Timer(_skeletonThreshold, () {
 90	      if (mounted) {
 91	        setState(() => _showSkeleton = true);
 92	      }
 93	    });
 94	    _scrollController.addListener(_onScroll);
 95	  }
