 97	  @override
 98	  void dispose() {
 99	    _skeletonTimer?.cancel();
100	    _searchSkeletonTimer?.cancel();
101	    _scrollController
102	      ..removeListener(_onScroll)
103	      ..dispose();
104	    super.dispose();
105	  }
