109	  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
110	  /// but re-armed per search rather than once per screen visit; any other
111	  /// state (including a fast resolve before the 300ms threshold, RNF01)
112	  /// cancels it and resets [_showSearchSkeleton].
113	  void _onSearchStateChanged(
114	    BuildContext context,
115	    Resource<List<Entry>> state,
116	  ) {
117	    _searchSkeletonTimer?.cancel();
118	    if (state is ResourceLoading<List<Entry>>) {
119	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
120	        if (mounted) {
121	          setState(() => _showSearchSkeleton = true);
122	        }
123	      });
124	      return;
125	    }
126	    if (_showSearchSkeleton) {
127	      setState(() => _showSearchSkeleton = false);
128	    }
129	  }
