588	/// "Hoje"/"Ontem"/`dd/mm/yyyy` — presentation's own job (Code Map: day
589	/// labels aren't the pure `groupEntriesByDate()`'s concern). [date] is
590	/// always already truncated to local midnight (`EntryDateGroup`'s own
591	/// contract).
592	String _dayLabel(DateTime date) {
593	  final now = DateTime.now();
594	  final today = DateTime(now.year, now.month, now.day);
595	  final yesterday = today.subtract(const Duration(days: 1));
596	  if (date == today) {
597	    return 'Hoje';
598	  }
599	  if (date == yesterday) {
600	    return 'Ontem';
601	  }
602	  final day = date.day.toString().padLeft(2, '0');
603	  final month = date.month.toString().padLeft(2, '0');
604	  return '$day/$month/${date.year}';
605	}

