 11	/// Drives `MeusRegistrosScreen` — calls `EntriesRepository.list()` directly
 12	/// (no use-case layer, matching this codebase's existing small-scope
 13	/// convention: `AccountSettingsCubit`/`AuthCubit`/`TextEntryCubit`). A
 14	/// `lazySingleton` (Code Map), like `AccountSettingsCubit` — long-lived, so
 15	/// the already-fetched pages survive leaving and re-entering
 16	/// `/meus-registros` within the same app session.
 17	///
 18	/// spec-4-2 — also subscribes to [PendingEntryWriteTracker.pendingWrites]/
 19	/// `.confirmedWrites` for this cubit's whole lifetime (constructor-wired,
 20	/// not `loadFirstPage()`-wired): both streams are shared singleton
 21	/// broadcasts a capture cubit on a *different* screen can drive at any
 22	/// time, and this cubit is itself a long-lived singleton that must reflect
 23	/// them regardless of which screen is currently visible.
 24	class MeusRegistrosCubit extends Cubit<MeusRegistrosState> {
 25	  MeusRegistrosCubit(this._repository, this._tracker)
 26	    : super(const MeusRegistrosLoading()) {
 27	    _pendingSubscription = _tracker.pendingWrites.listen(
 28	      _onPendingWritesChanged,
 29	    );
 30	    _confirmedSubscription = _tracker.confirmedWrites.listen(
 31	      _onEntryConfirmed,
 32	    );
 33	  }
 34	
 35	  final EntriesRepository _repository;
 36	  final PendingEntryWriteTracker _tracker;
 37	  late final StreamSubscription<List<PendingEntryWrite>> _pendingSubscription;
 38	  late final StreamSubscription<({String tempId, Entry entry})>
 39	  _confirmedSubscription;
 40	
 41	  /// Mirrors the tracker's own latest snapshot regardless of [state]'s
 42	  /// current type — so a pending write that arrives while [state] is
 43	  /// still [MeusRegistrosLoading]/[MeusRegistrosError] isn't lost: the
 44	  /// next [loadFirstPage] that resolves into [MeusRegistrosLoaded]/
 45	  /// [MeusRegistrosEmpty] seeds itself from this field directly.
 46	  List<PendingEntryWrite> _pendingWrites = const [];
 47	
 48	  /// A monotonic counter guarding against a stale in-flight call's result
 49	  /// landing after a newer call has already changed the state (e.g. the
 50	  /// user leaves and quickly re-enters `/meus-registros` while a slow
 51	  /// first request is still pending, or taps retry before the original
 52	  /// request resolves). Incremented at the start of every [loadFirstPage],
 53	  /// then captured locally before each `await` in [loadFirstPage]/
 54	  /// [_fetchMore] — a result whose captured generation no longer matches
 55	  /// this counter by the time it resolves is discarded rather than
 56	  /// emitted.
 57	  int _generation = 0;
 58	
 59	  void _onPendingWritesChanged(List<PendingEntryWrite> pendingWrites) {
 60	    _pendingWrites = pendingWrites;
 61	    final current = state;
 62	    if (current is MeusRegistrosLoaded) {
 63	      emit(current.copyWith(pendingWrites: pendingWrites));
 64	    } else if ((current is MeusRegistrosEmpty || current is MeusRegistrosError) &&
 65	        pendingWrites.isNotEmpty) {
 66	      // A capture save starts while this screen is showing "no entries
 67	      // yet" or a load failure (Review finding: the latter previously
 68	      // fell through this check entirely, silently dropping the pending
 69	      // card) — its own placeholder card must still show immediately
 70	      // (Acceptance Criteria), not wait for a reload.
 71	      emit(
 72	        MeusRegistrosLoaded(
 73	          entries: const [],
 74	          nextCursor: null,
 75	          pendingWrites: pendingWrites,
 76	        ),
 77	      );
 78	    }
 79	    // MeusRegistrosLoading: nothing to overlay onto yet — [_pendingWrites]
 80	    // above already keeps the latest snapshot, which the next
 81	    // loadFirstPage() resolution reads directly.
 82	  }
 83	
 84	  void _onEntryConfirmed(({String tempId, Entry entry}) confirmation) {
 85	    final entry = confirmation.entry;
 86	    // Review finding: drops this write's own pending placeholder from
 87	    // this cubit's *local* record synchronously with prepending the
 88	    // confirmed entry, in the very same handler — the tracker's own
 89	    // `pendingWrites` stream will also eventually deliver the matching
 90	    // removal, but that's a separate `Stream.multi`-wrapped subscription
 91	    // that can land one microtask late, which previously left a one-frame
 92	    // window where both the stale placeholder and the real confirmed
 93	    // entry rendered at once.
 94	    _pendingWrites = [
 95	      for (final pending in _pendingWrites)
 96	        if (pending.tempId != confirmation.tempId) pending,
 97	    ];
 98	    final current = state;
 99	    if (current is MeusRegistrosLoaded) {
100	      // Prepended, not reloaded (Design Notes) — preserves this cubit's
101	      // own pagination state (`nextCursor`/`loadMoreFailed`) exactly as
102	      // `loadMore()`'s own cursor-overlap robustness already relies on;
103	      // `_dedupedById` (unchanged) absorbs the degenerate case where a
104	      // later `list()`/`loadMore()` page's cursor also happens to repeat
105	      // this same (now server-known) id.
106	      emit(
107	        current.copyWith(
108	          entries: _dedupedById([entry, ...current.entries]),
109	          pendingWrites: _pendingWrites,
110	        ),
111	      );
112	    } else if (current is MeusRegistrosEmpty || current is MeusRegistrosError) {
113	      // Review finding: MeusRegistrosError previously fell through this
114	      // check too, same rationale as `_onPendingWritesChanged` above.
115	      emit(
116	        MeusRegistrosLoaded(
117	          entries: [entry],
118	          nextCursor: null,
119	          pendingWrites: _pendingWrites,
120	        ),
121	      );
122	    }
123	    // MeusRegistrosLoading: the next loadFirstPage() fetches the server's
124	    // own fresh page, which already includes this entry now that it's
125	    // confirmed server-side — nothing to reconcile.
126	  }
127	
128	  /// `EntryRecordCard`'s own retry tap (`MeusRegistrosScreen`) — forwards
129	  /// to the shared tracker verbatim (Never: "a second retry endpoint").
130	  Future<void> retry(String tempId) => _tracker.retry(tempId);
131	
132	  /// `MeusRegistrosScreen.initState` calls this once, every mount — always
133	  /// re-fetches from scratch rather than keeping a previous visit's page
134	  /// around, since a new entry may have been saved (Insertion Modal, Epic
135	  /// 3) since the last visit.
136	  Future<void> loadFirstPage() async {
137	    final generation = ++_generation;
138	    emit(const MeusRegistrosLoading());
139	    final result = await _repository.list();
140	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: `close()`
141	    // can race this awaited call (e.g. a fast app teardown mid-request) —
142	    // `emit()` after `close()` would otherwise throw.
143	    if (isClosed || generation != _generation) {
144	      return;
145	    }
146	    result.match(
147	      (failure) {
148	        // Review finding (round 2): mirrors the success branch's own
149	        // `_pendingWrites` overlay below — a write already pending/failed
150	        // when the first page fails to load must still show its own
151	        // placeholder card, not disappear behind a plain error screen
152	        // until the next unrelated `pendingWrites` emission.
153	        if (_pendingWrites.isEmpty) {
154	          emit(MeusRegistrosError(message: failure.message));
155	          return;
156	        }
157	        emit(
158	          MeusRegistrosLoaded(
159	            entries: const [],
160	            nextCursor: null,
161	            pendingWrites: _pendingWrites,
162	          ),
163	        );
164	      },
165	      (page) {
166	        // Same degenerate-cursor distrust as `_fetchMore`'s own guard below:
167	        // a page reporting zero items is treated as exhausted regardless of
168	        // `page.nextCursor` — an empty first page with a non-null cursor
169	        // would otherwise strand the user on `MeusRegistrosEmpty` with no
170	        // way back to a cursor this state no longer tracks. Forced
171	        // unconditionally (Review finding, round 1): independent of
172	        // `_pendingWrites` below — a pending write outstanding over an
173	        // otherwise-empty first page must still null out the cursor, not
174	        // just skip the `MeusRegistrosEmpty` branch beneath it.
